-- ======================================================================================
-- SISTEM TRACKING & INSPEKSI APAR ARMADA RIG - PT BUMI MEKAR SAKTI (BMS)
-- Database: PostgreSQL / Supabase
-- Modul: Terintegrasi untuk Modul User (HFO) & Modul Admin Pusat
-- Tanggal Dibuat: 2026-11-23
-- ======================================================================================

-- 1. DROP EXISTING TABLES (Urutan Child -> Parent)
DROP TABLE IF EXISTS maintenances CASCADE;
DROP TABLE IF EXISTS inspections CASCADE;
DROP TABLE IF EXISTS apars CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS apar_types CASCADE;
DROP TABLE IF EXISTS rigs CASCADE;

-- 2. CREATE SCHEMA TABLES
-- 2.1 TABEL MASTER RIG (16 Rig Operasional BMS)
CREATE TABLE rigs (
  id VARCHAR(20) PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  location VARCHAR(100) NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2.2 TABEL TIPE APAR (7 Tipe Standar Industri Termasuk Aturan CO2)
CREATE TABLE apar_types (
  id VARCHAR(50) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  capacity VARCHAR(50) NOT NULL,
  agent VARCHAR(50) NOT NULL,
  has_pressure_gauge BOOLEAN NOT NULL DEFAULT TRUE, -- False khusus CO2
  description TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2.3 TABEL PENGGUNA (48 Personel HFO + Akun Admin Pusat)
CREATE TABLE users (
  id VARCHAR(50) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(100) UNIQUE,
  rig_id VARCHAR(20) REFERENCES rigs(id) ON DELETE SET NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'user', -- 'user' (HFO) atau 'admin' (Pusat)
  position VARCHAR(50) DEFAULT 'HFO',
  password VARCHAR(100) NOT NULL DEFAULT '123456',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2.4 TABEL MASTER TABUNG APAR (224 Unit di 16 Rig)
CREATE TABLE apars (
  id VARCHAR(50) PRIMARY KEY,
  rig_id VARCHAR(20) NOT NULL REFERENCES rigs(id) ON DELETE CASCADE,
  type_id VARCHAR(50) NOT NULL REFERENCES apar_types(id) ON DELETE RESTRICT,
  asset_code VARCHAR(50) NOT NULL UNIQUE,
  brand VARCHAR(50),
  serial_no VARCHAR(50),
  capacity VARCHAR(50),
  location VARCHAR(100) NOT NULL,
  charge_owner VARCHAR(20) NOT NULL DEFAULT 'BMS', -- 'BMS' atau 'APM'
  manufacture_date DATE,
  has_pressure_gauge BOOLEAN NOT NULL DEFAULT TRUE,
  status VARCHAR(30) NOT NULL DEFAULT 'layak', -- 'layak' atau 'perlu_perbaikan'
  last_inspection_date DATE,
  last_inspection_status VARCHAR(30) DEFAULT 'layak',
  last_inspected_by VARCHAR(100),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2.5 TABEL LOG INSPEKSI FISIK 7 TITIK
CREATE TABLE inspections (
  id VARCHAR(50) PRIMARY KEY,
  apar_id VARCHAR(50) NOT NULL REFERENCES apars(id) ON DELETE CASCADE,
  asset_code VARCHAR(50) NOT NULL,
  rig_id VARCHAR(20) NOT NULL REFERENCES rigs(id) ON DELETE CASCADE,
  inspector_name VARCHAR(100) NOT NULL,
  inspection_date DATE NOT NULL,
  category VARCHAR(30) NOT NULL DEFAULT 'bulanan', -- 'bulanan' (Kru Rig) / 'tahunan' (Vendor Pihak ke-3)
  third_party_vendor VARCHAR(100),
  checklist JSONB NOT NULL, -- {handle, hose, nozle, pengamanTabung, pinSegel, pressureGauge, tabung}
  overall_status VARCHAR(30) NOT NULL, -- 'layak' / 'tidak_layak'
  issue_description TEXT,
  finding_photo TEXT, -- URL atau Base64 terkompresi (< 300KB)
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2.6 TABEL TIKET PERBAIKAN WORK ORDER
CREATE TABLE maintenances (
  id VARCHAR(50) PRIMARY KEY,
  apar_id VARCHAR(50) NOT NULL REFERENCES apars(id) ON DELETE CASCADE,
  asset_code VARCHAR(50) NOT NULL,
  rig_id VARCHAR(20) NOT NULL REFERENCES rigs(id) ON DELETE CASCADE,
  inspector_name VARCHAR(100),
  reported_by VARCHAR(100) NOT NULL,
  reported_date DATE NOT NULL,
  issue_description TEXT NOT NULL,
  finding_photo TEXT,
  status VARCHAR(30) NOT NULL DEFAULT 'open', -- 'open' -> 'in_progress' -> 'pending_review' -> 'closed'
  repair_notes TEXT,
  evidence_photo TEXT,
  evidence_uploaded_by VARCHAR(100),
  verified_by VARCHAR(100),
  verified_date DATE,
  admin_feedback TEXT,
  updated_at DATE DEFAULT CURRENT_DATE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. INDEX UNTUK PERFORMA QUERY CEPAT
CREATE INDEX idx_apars_rig ON apars(rig_id);
CREATE INDEX idx_apars_status ON apars(status);
CREATE INDEX idx_inspections_apar ON inspections(apar_id);
CREATE INDEX idx_inspections_rig_date ON inspections(rig_id, inspection_date);
CREATE INDEX idx_maintenances_status ON maintenances(status);
CREATE INDEX idx_maintenances_rig ON maintenances(rig_id);

-- ======================================================================================
-- 4. INSERT MASTER & SEED DATA
-- ======================================================================================

-- 4.1 INSERT 16 RIG OPERASIONAL BMS

-- 4.2 INSERT 7 TIPE MASTER APAR

