-- ======================================================================================
-- 5. FUNCTION & TRIGGER: SINKRONISASI STATUS APAR OTOMATIS
-- Saat tiket maintenance diubah menjadi 'closed' oleh Admin, status APAR otomatis pulih jadi 'layak'
-- ======================================================================================
CREATE OR REPLACE FUNCTION trg_fn_sync_apar_on_ticket_close()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status = 'closed' AND OLD.status != 'closed' THEN
    UPDATE apars
    SET status = 'layak',
        last_inspection_status = 'layak'
    WHERE id = NEW.apar_id;
  ELSIF NEW.status IN ('open', 'in_progress', 'pending_review') THEN
    UPDATE apars
    SET status = 'perlu_perbaikan'
    WHERE id = NEW.apar_id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_sync_apar_status ON maintenances;
CREATE TRIGGER trg_sync_apar_status
AFTER UPDATE OF status ON maintenances
FOR EACH ROW
EXECUTE FUNCTION trg_fn_sync_apar_on_ticket_close();

-- SELESAI: Skema & Data Seed Siap Digunakan di Supabase
